import { Inject, Injectable, Logger, Optional, forwardRef } from '@nestjs/common';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { CustomerService } from '../customer/customer.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Optional() @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService
    ) {}

    /**
     * Generates the billing report (invoice + billing ledger record) for a single customer.
     * The job is scheduled per customer, the businessID lives on the scheduler record while the
     * customerId is passed along inside the scheduleParameters.
     */
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters, businessID } }: Job<SchedulerEntity>) {
        const { customerId } = (scheduleParameters ?? {}) as CreateBillingReportDto;
        try {
            // 1. Resolve the customer and the offering it is attached to
            const {
                data: [customer],
            } = await this.customerService.findOne({ customerId, businessID });
            const offering = customer?.offering;
            if (!offering) {
                BillingService.logger.log(
                    `No offering found for customer: ${customerId} in business: ${businessID}, skipping billing report`
                );
                return;
            }
            // 2. The billing cycle of the offering determines the time range that gets billed
            const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle);
            // 3. Generate the invoice out of the total usage of the customer for that time range
            const { invoiceId } = await this.invoicesService.generateInvoiceForUsageTotal({
                businessID,
                customerId,
                start: startTime,
                end: endTime,
            });
            // 4. Save the billing information to the Ledger
            const entity = new Billing({
                invoiceId,
                businessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });
            const point = Billing.transformer(entity, this.InfluxService);
            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'enterprise', [point]);
        } catch (e) {
            BillingService.logger.error(
                `Error while generating the billing report for customer: ${customerId} in business: ${businessID}`,
                e?.stack
            );
            AuditService.publishEvent({
                message: `Error while generating the billing report for customer: ${customerId} in business: ${businessID}`,
                data: [e],
                topic: AuditScope.ERROR,
            });
        }
    }
}

