import { Point } from '@influxdata/influxdb-client';
import { NotFoundException } from '@nestjs/common';
import { CustomerService } from '../customer/customer.service';
import { BillingService } from '../billing/billing.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { UsageService } from '../usage/usage.service';
import { AuditService } from '../audit/audit.service';
import { schedulerType, SchedulerStatus, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto';
import { billingScheduleConsumers, Billing } from '../billing/entities/billing.entity';

const influxMock = () =>
    ({
        loadPoints: jest.fn(),
        getPoint: (m: string) => new Point(m),
    } as any);

describe('migration', () => {
    it('creates a billing schedule only with an offering', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() } as any;
        const service = new CustomerService(influxMock(), scheduler, {} as any, {} as any, {} as any);
        await service.create(
            { customerName: 'a', email: 'a@b.c', paymentChannel: null, businessID: 'biz' } as any,
            'sub|1'
        );
        expect(scheduler.create).not.toHaveBeenCalled();

        await service.create(
            { customerName: 'a', email: 'a@b.c', paymentChannel: null, businessID: 'biz', offeringId: 'off' } as any,
            'sub|1'
        );
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                rate: SupportedMeasurementFrequencies.monthly,
                subject: 'sub|1',
                businessID: 'biz',
            })
        );
    });

    it('replaces the schedule when the offering changes, missing old schedule is fine', async () => {
        const scheduler = {
            create: jest.fn(),
            remove: jest.fn().mockRejectedValue(new NotFoundException('nope')),
        } as any;
        const service = new CustomerService(influxMock(), scheduler, {} as any, {} as any, {} as any);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: 'cust', customerName: 'a', offeringId: 'old' } as any],
            message: '',
        });
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'new' } as any, 'sub|1');
        expect(scheduler.remove).toHaveBeenCalledWith({
            schedulerID: 'cust',
            businessID: 'biz',
            isBillingQueue: true,
        });
        expect(scheduler.create).toHaveBeenCalledWith({
            schedulerID: 'cust',
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId: 'cust', businessID: 'biz' },
            rate: SupportedMeasurementFrequencies.monthly,
            subject: 'sub|1',
            businessID: 'biz',
        });

        scheduler.create.mockClear();
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'old' } as any, 'sub|1');
        expect(scheduler.create).not.toHaveBeenCalled();
    });

    it('runs the billing report for a customer', async () => {
        const influx = influxMock();
        const customerService = {
            findOne: jest.fn().mockResolvedValue({
                data: [{ customerId: 'cust', offering: { billingCycle: 'monthly' } }],
                message: '',
            }),
        } as any;
        const invoices = { generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'inv-1' }) } as any;
        const billing = new BillingService(influx, customerService, invoices);
        await billing.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } } } as any);
        const { startTime, endTime } = Billing.billingCycleToTimeRange('monthly' as any);
        expect(customerService.findOne).toHaveBeenCalledWith({ customerId: 'cust', businessID: 'biz' });
        expect(invoices.generateInvoiceForUsageTotal).toHaveBeenCalledWith({
            businessID: 'biz',
            customerId: 'cust',
            start: startTime,
            end: endTime,
        });
        const [[bucket, org, points]] = influx.loadPoints.mock.calls;
        expect(points[0].toString()).toContain('inv-1');
        expect(org).toEqual('enterprise');
    });

    it('audits billing failures', async () => {
        const influx = influxMock();
        const customerService = { findOne: jest.fn().mockRejectedValue(new Error('boom')) } as any;
        const invoices = { generateInvoiceForUsageTotal: jest.fn() } as any;
        const publish = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        const billing = new BillingService(influx, customerService, invoices);
        await expect(
            billing.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } } } as any)
        ).resolves.toBeUndefined();
        expect(publish).toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
        publish.mockRestore();
    });

    it('emits billing jobs to the billing queue', async () => {
        const queue = { add: jest.fn() } as any;
        const billingQueue = { add: jest.fn() } as any;
        const scheduler = new SchedulerService(queue, billingQueue);
        await scheduler.emitOne({
            schedulerId: 'sched',
            payload: { schedulerType: schedulerType.billing, scheduleParameters: { customerId: 'cust' } },
        });
        expect(billingQueue.add).toHaveBeenCalledWith(
            billingScheduleConsumers.billingReport,
            expect.objectContaining({ schedulerID: 'sched', scheduleParameters: { customerId: 'cust' } })
        );
        expect(queue.add).not.toHaveBeenCalled();

        await scheduler.emitOne({
            schedulerId: 'sched2',
            payload: { schedulerType: schedulerType.dimensionDataGathering, dimensionType: 'ebsVolume' },
        });
        expect(queue.add).toHaveBeenCalledWith('ebsVolume', expect.objectContaining({ schedulerID: 'sched2' }));
    });

    it('returns empty usage when the customer has no offering', async () => {
        const customerService = {
            findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'cust' }], message: '' }),
        } as any;
        const usage = new UsageService(influxMock(), {} as any, {} as any, customerService, {} as any);
        await expect(usage.findUsageForCustomer({ customerId: 'cust', businessID: 'biz' }, {})).resolves.toEqual([]);
    });
});

